      const prev=document.createElement('button');prev.type='button';prev.className='product-side-arrow product-side-prev';prev.dataset.railTarget=trackId;prev.dataset.railDirection='-1';prev.setAttribute('aria-label','Produk sebelumnya');prev.innerHTML='<span aria-hidden="true">‹</span>';
      const next=document.createElement('button');next.type='button';next.className='product-side-arrow product-side-next';next.dataset.railTarget=trackId;next.dataset.railDirection='1';next.setAttribute('aria-label','Produk berikutnya');next.innerHTML='<span aria-hidden="true">›</span>';
