      console.error('SIMBAA products query failed:',err);
      const status=$('#catalogStatus');if(status)status.textContent='Produk belum dapat dimuat dari Supabase. Periksa akses Data API/GRANT SELECT, policy RLS publik, lalu jalankan migration-v18-admin-storefront.sql.';
